from base64 import b64encode
def img2b64(
    path:Path,
)->str:
    "Encode an image file as a base64 data URL."
    return 'data:image/png;base64,'+b64encode(Path.read_bytes(path)).decode()

# %% ../nbs/00_core.ipynb #28071d39
@delegates(stream, keep=True)
def session(
    **kwargs,
):
    "Create a stream partial with preset model/kwargs."
    return partial(stream, **kwargs)

# %% ../nbs/00_core.ipynb #b024c39d
async def _process_frame(session, run_id:int, p:Path, prompt:str, prompt_type:str):
    "Run VLM on a single frame and store the result."
    r = await session([user(prompt, img=img2b64(p))])
    runframes.insert(run_id=run_id, frame_id=p.stem.split('_')[1], type=prompt_type, prompt=prompt, description=r.message.text, usage=r.usage.raw)

