from fastprogress.fastprogress import NBMasterBar as master_bar
async def deploy_run(
    video_id:int,
    session,
    pth:list,
    prompt:str,
    prompt_type:str,
    start:int=0,
    stop:int|None=None,
    step:int=1,
    cache:bool=False,
)->Run:
    "Run a single prompt across a range of frames, storing results in the database."
    if stop is None: stop = len(pth)
    if not cache: disable_cachy(); print('!! Cache disabled')
    else: print('!! Using cache')

    run = runs.insert(deploy_time=datetime.now(tz), video_id=video_id, model=session.keywords['model'], num_frames=(stop-start)//step)
    _run_header(run, session.keywords['model'], start, stop, step, cache)

    for p in (mb:=master_bar(pth[start:stop:step])):
        mb.main_bar.comment = f'frame {p.stem.split("_")[1]}'
        await _process_frame(session, run.id, p, prompt, prompt_type)

    if not cache: enable_cachy(); print('!! Cache enabled')
    return _finish_run(run.id)

